    instance_id VARCHAR(160) NOT NULL,
    host_alias VARCHAR(160) NOT NULL,
    port_no INT NOT NULL,
    profile_name VARCHAR(80) NOT NULL,
    zone_id VARCHAR(80) NULL,
    pool_id VARCHAR(80) NULL,
    agent_base_url VARCHAR(500) NOT NULL,
    config_ref VARCHAR(1000) NULL,
    desired_state VARCHAR(32) NOT NULL,
    CONSTRAINT PK_BAT_DEPLOYMENT_INSTANCE PRIMARY KEY (cell_id, instance_id),
    CONSTRAINT uk_bat_deployment_instance_id UNIQUE (instance_id),
    CONSTRAINT fk_bat_deployment_instance_cell FOREIGN KEY (cell_id) REFERENCES BAT_DEPLOYMENT_CELL (cell_id) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_DEPLOYMENT_INSTANCE COMMENT = 'BAT deployment cell instance projection';

CREATE TABLE BAT_EXECUTION_LINK (
    cpf_execution_id VARCHAR(80) NOT NULL,
    link_key VARCHAR(80) NOT NULL,
    job_id VARCHAR(80) NOT NULL,
    definition_version BIGINT NOT NULL,
    spring_job_instance_id BIGINT NOT NULL,
    spring_job_execution_id BIGINT NOT NULL,
    spring_step_execution_id BIGINT NULL,
    spring_status VARCHAR(40) NOT NULL,
    fencing_token BIGINT NOT NULL,
    created_at DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
    updated_at DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6) NOT NULL ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT PK_BAT_EXECUTION_LINK PRIMARY KEY (cpf_execution_id, link_key),
    CONSTRAINT ck_cpf_bat_link_fencing CHECK (fencing_token > 0),
    CONSTRAINT fk_cpf_bat_exec_link FOREIGN KEY (cpf_execution_id) REFERENCES BAT_EXECUTION_CONTROL (cpf_execution_id) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_EXECUTION_LINK COMMENT = 'CPF 실행과 Spring Batch Job/Step Metadata 연결 Projection';
CREATE INDEX ix_cpf_bat_link_sb ON BAT_EXECUTION_LINK (spring_job_execution_id, spring_step_execution_id);

CREATE TABLE BAT_JOB (
    job_id VARCHAR(100) NOT NULL,
    job_name VARCHAR(150) NOT NULL,
    job_type VARCHAR(30) DEFAULT 'TASKLET' NOT NULL,
    description VARCHAR(500) NULL,
    restartable_yn CHAR(1) DEFAULT 'Y' NOT NULL,
    use_yn CHAR(1) DEFAULT 'Y' NOT NULL,
    created_by VARCHAR(100) DEFAULT 'BAT' NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(100) DEFAULT 'BAT' NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL ON UPDATE CURRENT_TIMESTAMP,
    published_definition_version BIGINT NULL,
    published_definition_checksum VARCHAR(128) NULL,
    executor_reference VARCHAR(300) NULL,
    definition_published_at DATETIME(3) NULL,
    CONSTRAINT PK_BAT_JOB PRIMARY KEY (job_id),
    CONSTRAINT fk_bat_job_published_definition FOREIGN KEY (job_id, published_definition_version) REFERENCES BAT_JOB_DEFINITION_VERSION (job_id, definition_version)
) ENGINE=InnoDB;
ALTER TABLE BAT_JOB COMMENT = 'BAT 배치 Job 기준';
CREATE INDEX ix_bat_job_use ON BAT_JOB (use_yn, job_type);

CREATE TABLE BAT_JOB_DEPENDENCY (
    job_id VARCHAR(100) NOT NULL,
    definition_version BIGINT NOT NULL,
    related_job_id VARCHAR(80) NOT NULL,
    condition_code VARCHAR(40) NOT NULL,
    timeout_seconds BIGINT DEFAULT 0 NOT NULL,
    required_yn CHAR(1) DEFAULT 'Y' NOT NULL,
    sort_order INT DEFAULT 0 NOT NULL,
    CONSTRAINT PK_BAT_JOB_DEPENDENCY PRIMARY KEY (job_id, definition_version, related_job_id),
    CONSTRAINT ck_bat_job_dep_self CHECK (job_id <> related_job_id),
    CONSTRAINT fk_bat_job_dep_def FOREIGN KEY (job_id, definition_version) REFERENCES BAT_JOB_DEFINITION_VERSION (job_id, definition_version) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_JOB_DEPENDENCY COMMENT = 'BAT Versioned Job Dependency';

CREATE TABLE BAT_JOB_PARAMETER_DEFINITION (
    job_id VARCHAR(100) NOT NULL,
    definition_version BIGINT NOT NULL,
    parameter_name VARCHAR(100) NOT NULL,
    parameter_type VARCHAR(40) NOT NULL,
    label_text VARCHAR(200) NULL,
    description_text VARCHAR(1000) NULL,
    required_yn CHAR(1) DEFAULT 'N' NOT NULL,
    sensitive_yn CHAR(1) DEFAULT 'N' NOT NULL,
    default_value VARCHAR(1000) NULL,
    allowed_values TEXT NULL,
    validation_pattern VARCHAR(1000) NULL,
    min_value DECIMAL(38,10) NULL,
    max_value DECIMAL(38,10) NULL,
    min_length INT NULL,
    max_length INT NULL,
    reference_type VARCHAR(80) NULL,
    alias_required_yn CHAR(1) DEFAULT 'N' NOT NULL,
    runtime_override_allowed_yn CHAR(1) DEFAULT 'N' NOT NULL,
    sort_order INT DEFAULT 0 NOT NULL,
    CONSTRAINT PK_BAT_JOB_PARAMETER_DEFINITION PRIMARY KEY (job_id, definition_version, parameter_name),
    CONSTRAINT fk_bat_job_param_def FOREIGN KEY (job_id, definition_version) REFERENCES BAT_JOB_DEFINITION_VERSION (job_id, definition_version) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_JOB_PARAMETER_DEFINITION COMMENT = 'BAT Typed Parameter Schema';

CREATE TABLE BAT_JOB_RUNTIME_PROJECTION (
    job_id VARCHAR(100) NOT NULL,
    definition_version BIGINT NOT NULL,
    definition_checksum VARCHAR(64) NOT NULL,
    projection_status VARCHAR(30) DEFAULT 'ACTIVE' NOT NULL,
    executor_type VARCHAR(40) NOT NULL,
    executor_reference VARCHAR(300) NOT NULL,
    trigger_type VARCHAR(30) NOT NULL,
    trigger_expression VARCHAR(500) NULL,
    timezone_id VARCHAR(100) NOT NULL,
    projection_json LONGTEXT NOT NULL,
    projection_hash VARCHAR(64) NOT NULL,
    effective_from DATETIME NULL,
    effective_until DATETIME NULL,
    published_by VARCHAR(100) NOT NULL,
    published_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    retired_at DATETIME NULL,
    row_version BIGINT DEFAULT 1 NOT NULL,
    CONSTRAINT PK_BAT_JOB_RUNTIME_PROJECTION PRIMARY KEY (job_id, definition_version),
    CONSTRAINT fk_bat_job_projection_definition FOREIGN KEY (job_id, definition_version) REFERENCES BAT_JOB_DEFINITION_VERSION (job_id, definition_version)
) ENGINE=InnoDB;
ALTER TABLE BAT_JOB_RUNTIME_PROJECTION COMMENT = 'Published Batch Definition Runtime 정본';
CREATE INDEX ix_bat_job_projection_status ON BAT_JOB_RUNTIME_PROJECTION (projection_status, effective_from, effective_until);
CREATE UNIQUE INDEX ix_bat_job_projection_hash ON BAT_JOB_RUNTIME_PROJECTION (projection_hash);

CREATE TABLE BAT_JOB_RUNTIME_PROJECTION_OUTBOX (
    outbox_id VARCHAR(100) NOT NULL,
    job_id VARCHAR(100) NOT NULL,
    definition_version BIGINT NOT NULL,
    event_type VARCHAR(40) NOT NULL,
    payload_hash VARCHAR(64) NOT NULL,
    event_payload LONGTEXT NOT NULL,
    delivery_status VARCHAR(30) DEFAULT 'PENDING' NOT NULL,
    lease_owner VARCHAR(100) NULL,
    lease_until DATETIME NULL,
    fencing_token BIGINT DEFAULT 0 NOT NULL,
    attempt_count INT DEFAULT 0 NOT NULL,
    next_attempt_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_error_code VARCHAR(100) NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    delivered_at DATETIME NULL,
    CONSTRAINT PK_BAT_JOB_RUNTIME_PROJECTION_OUTBOX PRIMARY KEY (outbox_id),
    CONSTRAINT fk_bat_projection_outbox_definition FOREIGN KEY (job_id, definition_version) REFERENCES BAT_JOB_DEFINITION_VERSION (job_id, definition_version)
) ENGINE=InnoDB;
ALTER TABLE BAT_JOB_RUNTIME_PROJECTION_OUTBOX COMMENT = 'Batch Runtime Projection Durable Outbox';
CREATE INDEX ix_bat_projection_outbox_claim ON BAT_JOB_RUNTIME_PROJECTION_OUTBOX (delivery_status, next_attempt_at, lease_until);
CREATE INDEX ix_bat_projection_outbox_job ON BAT_JOB_RUNTIME_PROJECTION_OUTBOX (job_id, definition_version, created_at);

CREATE TABLE BAT_JOB_PACK_JOB (
    job_pack_id VARCHAR(120) NOT NULL,
    job_id VARCHAR(100) NOT NULL,
    restartable_yn CHAR(1) NOT NULL,
    center_cut_provider_key VARCHAR(100) NULL,
    center_cut_handler_key VARCHAR(100) NULL,
    CONSTRAINT PK_BAT_JOB_PACK_JOB PRIMARY KEY (job_pack_id, job_id),
    CONSTRAINT fk_bat_job_pack_job_pack FOREIGN KEY (job_pack_id) REFERENCES BAT_JOB_PACK (job_pack_id) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_JOB_PACK_JOB COMMENT = 'BAT job-pack job projection';

CREATE TABLE BAT_RUNTIME_COMMAND_ATTEMPT (
    attempt_id BIGINT AUTO_INCREMENT NOT NULL,
    command_id VARCHAR(80) NOT NULL,
    attempt_no INT NOT NULL,
    instance_id VARCHAR(160) NULL,
    stage_code VARCHAR(80) NOT NULL,
    attempt_state VARCHAR(40) NOT NULL,
    result_message VARCHAR(4000) NULL,
    started_at DATETIME(6) NOT NULL,
    finished_at DATETIME(6) NULL,
    CONSTRAINT PK_BAT_RUNTIME_COMMAND_ATTEMPT PRIMARY KEY (attempt_id),
    CONSTRAINT uk_bat_runtime_command_attempt UNIQUE (command_id, attempt_no, instance_id, stage_code),
    CONSTRAINT fk_bat_runtime_command_attempt_command FOREIGN KEY (command_id) REFERENCES BAT_RUNTIME_COMMAND (command_id) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_RUNTIME_COMMAND_ATTEMPT COMMENT = 'BAT runtime command execution attempt';
CREATE INDEX ix_bat_runtime_command_attempt_instance ON BAT_RUNTIME_COMMAND_ATTEMPT (instance_id, started_at);

CREATE TABLE BAT_RUNTIME_CAPABILITY (
    instance_id VARCHAR(160) NOT NULL,
    capability_code VARCHAR(80) NOT NULL,
    CONSTRAINT PK_BAT_RUNTIME_CAPABILITY PRIMARY KEY (instance_id, capability_code),
    CONSTRAINT fk_bat_runtime_capability_instance FOREIGN KEY (instance_id) REFERENCES BAT_RUNTIME_INSTANCE (instance_id) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_RUNTIME_CAPABILITY COMMENT = 'BAT runtime capability projection';

CREATE TABLE BAT_RUNTIME_HEARTBEAT (
    heartbeat_id BIGINT AUTO_INCREMENT NOT NULL,
    instance_id VARCHAR(160) NOT NULL,
    heartbeat_at DATETIME(6) NOT NULL,
    ready_yn CHAR(1) NOT NULL,
    available_capacity INT DEFAULT 0 NOT NULL,
    queue_depth BIGINT DEFAULT 0 NOT NULL,
    draining_yn CHAR(1) DEFAULT 'N' NOT NULL,
    current_execution_count INT DEFAULT 0 NOT NULL,
    active_lease_count INT DEFAULT 0 NOT NULL,
    last_error_code VARCHAR(80) NULL,
    deployment_version VARCHAR(80) NULL,
    CONSTRAINT PK_BAT_RUNTIME_HEARTBEAT PRIMARY KEY (heartbeat_id),
    CONSTRAINT fk_bat_runtime_heartbeat_instance FOREIGN KEY (instance_id) REFERENCES BAT_RUNTIME_INSTANCE (instance_id) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE BAT_RUNTIME_HEARTBEAT COMMENT = 'BAT runtime heartbeat event';
CREATE INDEX ix_bat_runtime_heartbeat_instance ON BAT_RUNTIME_HEARTBEAT (instance_id, heartbeat_at);

CREATE TABLE BAT_SB_JOB_EXECUTION (
    JOB_EXECUTION_ID BIGINT NOT NULL,
    VERSION BIGINT NULL,
    JOB_INSTANCE_ID BIGINT NOT NULL,
    CREATE_TIME DATETIME(6) NOT NULL,
    START_TIME DATETIME(6) DEFAULT NULL NULL,
    END_TIME DATETIME(6) DEFAULT NULL NULL,
    STATUS VARCHAR(10) NULL,
    EXIT_CODE VARCHAR(2500) NULL,
    EXIT_MESSAGE VARCHAR(2500) NULL,
    LAST_UPDATED DATETIME(6) NULL,
    CONSTRAINT PK_BAT_SB_JOB_EXECUTION PRIMARY KEY (JOB_EXECUTION_ID),
    CONSTRAINT JOB_INST_EXEC_FK FOREIGN KEY (JOB_INSTANCE_ID) REFERENCES BAT_SB_JOB_INSTANCE (JOB_INSTANCE_ID)
) ENGINE=InnoDB;
ALTER TABLE BAT_SB_JOB_EXECUTION COMMENT = 'Spring Batch 표준 JobExecution 저장소';

CREATE TABLE CMN_TEMPLATE_AUDIT (
    AUDIT_ID VARCHAR(64) NOT NULL,
    TEMPLATE_CODE VARCHAR(100) NOT NULL,
    TEMPLATE_VERSION BIGINT NOT NULL,
    CHANNEL_CODE VARCHAR(30) NOT NULL,
    ACTION_TYPE VARCHAR(30) NOT NULL,
    REQUEST_USER VARCHAR(100) NOT NULL,
    REQUEST_REASON VARCHAR(500) NOT NULL,
    BEFORE_STATUS VARCHAR(30) NULL,
    AFTER_STATUS VARCHAR(30) NOT NULL,
    REVISION_NO BIGINT NOT NULL,
    OCCURRED_AT DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    CONSTRAINT PK_CMN_TEMPLATE_AUDIT PRIMARY KEY (AUDIT_ID),
    CONSTRAINT CK_CMN_TEMPLATE_AUDIT_ACTION CHECK (ACTION_TYPE IN ('CREATE_DRAFT','APPROVE','SUPERSEDE','RETIRE')),
    CONSTRAINT CK_CMN_TEMPLATE_AUDIT_REVISION CHECK (REVISION_NO >= 0),
    CONSTRAINT FK_CMN_TEMPLATE_AUDIT_DEFINITION FOREIGN KEY (TEMPLATE_CODE, TEMPLATE_VERSION, CHANNEL_CODE) REFERENCES CMN_TEMPLATE_DEFINITION (TEMPLATE_CODE, TEMPLATE_VERSION, CHANNEL_CODE)
) ENGINE=InnoDB;
ALTER TABLE CMN_TEMPLATE_AUDIT COMMENT = 'CMN Template 변경 append-only 감사 원장';
CREATE INDEX IX_CMN_TEMPLATE_AUDIT_LOOKUP ON CMN_TEMPLATE_AUDIT (TEMPLATE_CODE, CHANNEL_CODE, TEMPLATE_VERSION, OCCURRED_AT);

CREATE TABLE CPF_DATA_QUALITY_OPERATION (
    OPERATION_ID VARCHAR(160) NOT NULL,
    OPERATION_TYPE VARCHAR(64) NOT NULL,
    QUARANTINE_ID VARCHAR(64) NOT NULL,
    COMMAND_FINGERPRINT CHAR(64) NOT NULL,
    RESULT_PAYLOAD LONGBLOB NOT NULL,
    ACTOR_ID VARCHAR(64) NOT NULL,
    ACTION_REASON VARCHAR(1000) NOT NULL,
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_CPF_DATA_QUALITY_OPERATION PRIMARY KEY (OPERATION_ID),
    CONSTRAINT CK_CPF_DQ_OPERATION_HASH CHECK (CHAR_LENGTH(COMMAND_FINGERPRINT) = 64),
    CONSTRAINT FK_CPF_DQ_OPERATION_QUARANTINE FOREIGN KEY (QUARANTINE_ID) REFERENCES CPF_DATA_QUALITY_QUARANTINE (QUARANTINE_ID)
) ENGINE=InnoDB;
ALTER TABLE CPF_DATA_QUALITY_OPERATION COMMENT = 'Persistent DQ replay/reconcile idempotency ledger';
CREATE INDEX IX_CPF_DQ_OPERATION_TARGET ON CPF_DATA_QUALITY_OPERATION (QUARANTINE_ID, OPERATION_TYPE, CREATED_AT);

CREATE TABLE CPF_NOTIFICATION_DELIVERY_LOG (
    delivery_id BIGINT AUTO_INCREMENT NOT NULL,
    rule_id BIGINT NULL,
    event_type VARCHAR(80) NOT NULL,
    target_type VARCHAR(80) NULL,
    target_id VARCHAR(120) NULL,
    receiver VARCHAR(200) NULL,
    delivery_status VARCHAR(30) DEFAULT 'READY' NOT NULL,
    delivery_message VARCHAR(2000) NULL,
    requested_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    delivered_at DATETIME(3) NULL,
    created_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL ON UPDATE CURRENT_TIMESTAMP,
    operation_id VARCHAR(100) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
    payload_body VARCHAR(2000) NOT NULL,
    attempt_count INT DEFAULT 0 NOT NULL,
    max_attempts INT DEFAULT 3 NOT NULL,
    next_attempt_at DATETIME(3) NULL,
    lease_owner VARCHAR(100) NULL,
    lease_until DATETIME(3) NULL,
    version BIGINT DEFAULT 0 NOT NULL,
    last_error_code VARCHAR(80) NULL,
    CONSTRAINT PK_CPF_NOTIFICATION_DELIVERY_LOG PRIMARY KEY (delivery_id),
    CONSTRAINT uk_cpf_notification_delivery_operation UNIQUE (operation_id),
    CONSTRAINT fk_cpf_notification_delivery_rule FOREIGN KEY (rule_id) REFERENCES CPF_NOTIFICATION_RULE (rule_id) ON DELETE SET NULL
) ENGINE=InnoDB;
ALTER TABLE CPF_NOTIFICATION_DELIVERY_LOG COMMENT = 'CPF 운영 알림 발송 로그';
CREATE INDEX ix_cpf_notification_delivery_target ON CPF_NOTIFICATION_DELIVERY_LOG (target_type, target_id, requested_at);
CREATE INDEX ix_cpf_notification_delivery_status ON CPF_NOTIFICATION_DELIVERY_LOG (delivery_status, requested_at);
CREATE INDEX ix_cpf_notification_delivery_due ON CPF_NOTIFICATION_DELIVERY_LOG (delivery_status, next_attempt_at, lease_until);

CREATE TABLE CPF_SAGA_MANUAL_ACTION (
