    updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    CONSTRAINT PK_CPF_SAGA_STEP_EXECUTION PRIMARY KEY (saga_id, step_no),
    CONSTRAINT fk_cpf_saga_step_execution FOREIGN KEY (saga_id) REFERENCES CPF_SAGA_EXECUTION (saga_id)
) ENGINE=InnoDB;
ALTER TABLE CPF_SAGA_STEP_EXECUTION COMMENT = 'Saga 단계 실행 원장';
CREATE INDEX idx_cpf_saga_step_status ON CPF_SAGA_STEP_EXECUTION (step_status, updated_at);

CREATE TABLE CPF_TRANSACTION_LOG_DETAIL (
    DETAIL_ID BIGINT AUTO_INCREMENT NOT NULL,
    LOG_IDX BIGINT NOT NULL,
    DETAIL_KEY VARCHAR(100) DEFAULT 'N/A' NOT NULL,
    DETAIL_VALUE MEDIUMTEXT NOT NULL,
    created_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT PK_CPF_TRANSACTION_LOG_DETAIL PRIMARY KEY (DETAIL_ID),
    CONSTRAINT fk_cpf_transaction_log_detail_log FOREIGN KEY (LOG_IDX) REFERENCES CPF_TRANSACTION_LOG (LOG_IDX) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE CPF_TRANSACTION_LOG_DETAIL COMMENT = 'CPF 거래 상세 로그';
CREATE INDEX ix_cpf_transaction_log_detail_log_key ON CPF_TRANSACTION_LOG_DETAIL (LOG_IDX, DETAIL_KEY);

CREATE TABLE GW_RATE_LIMIT_REQUEST (
    counter_key VARCHAR(300) NOT NULL,
    policy_version BIGINT NOT NULL,
    window_start_ms BIGINT NOT NULL,
    request_id VARCHAR(200) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
    accepted INT NOT NULL,
    used_units BIGINT NOT NULL,
    remaining_units BIGINT NOT NULL,
    reset_at_ms BIGINT NOT NULL,
    blocked_until_ms BIGINT DEFAULT 0 NOT NULL,
    rejected_count INT DEFAULT 0 NOT NULL,
    reason VARCHAR(200) NOT NULL,
    limiting_index INT DEFAULT -1 NOT NULL,
    CONSTRAINT PK_GW_RATE_LIMIT_REQUEST PRIMARY KEY (counter_key, policy_version, window_start_ms, request_id),
    CONSTRAINT ck_gw_rate_limit_request_accepted CHECK (accepted IN (0,1)),
    CONSTRAINT fk_gw_rate_limit_request_counter FOREIGN KEY (counter_key, policy_version, window_start_ms) REFERENCES GW_RATE_LIMIT_COUNTER (counter_key, policy_version, window_start_ms)
) ENGINE=InnoDB;
ALTER TABLE GW_RATE_LIMIT_REQUEST COMMENT = 'Gateway Rate Limit 멱등 요청 Journal';
CREATE INDEX ix_gw_rate_limit_request_id ON GW_RATE_LIMIT_REQUEST (request_id);

CREATE TABLE GW_BINDING (
    binding_id VARCHAR(100) NOT NULL,
    route_id VARCHAR(100) NOT NULL,
    environment_code VARCHAR(50) NOT NULL,
    host_pattern VARCHAR(300) NOT NULL,
    path_pattern VARCHAR(500) NOT NULL,
    target_path VARCHAR(500) NOT NULL,
    http_method VARCHAR(20) DEFAULT '*' NOT NULL,
    api_version VARCHAR(50) NOT NULL,
    ingress_protocol VARCHAR(30) NOT NULL,
    target_protocol VARCHAR(30) NOT NULL,
    service_id VARCHAR(100) NOT NULL,
    server_group_id VARCHAR(100) NOT NULL,
    route_version VARCHAR(100) NOT NULL,
    tls_policy_id VARCHAR(100) NULL,
    authentication_policy_id VARCHAR(100) NULL,
    authorization_policy_id VARCHAR(100) NULL,
    header_policy_id VARCHAR(100) NULL,
    rate_limit_policy_id VARCHAR(100) NULL,
    health_policy_id VARCHAR(100) NULL,
    connect_timeout_ms INT NOT NULL,
    response_timeout_ms INT NOT NULL,
    overall_timeout_ms INT NOT NULL,
    max_retry_count INT DEFAULT 0 NOT NULL,
    idempotent_yn CHAR(1) DEFAULT 'N' NOT NULL,
    failover_group_id VARCHAR(100) NULL,
    gateway_allowed_yn CHAR(1) DEFAULT 'N' NOT NULL,
    direct_allowed_yn CHAR(1) DEFAULT 'N' NOT NULL,
    binding_status VARCHAR(30) DEFAULT 'DRAFT' NOT NULL,
    approval_id VARCHAR(100) NULL,
    effective_from DATETIME NULL,
    effective_to DATETIME NULL,
    created_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL ON UPDATE CURRENT_TIMESTAMP,
    row_version BIGINT DEFAULT 1 NOT NULL,
    binding_checksum VARCHAR(64) NULL,
    retired_by VARCHAR(100) NULL,
    retired_at DATETIME NULL,
    CONSTRAINT PK_GW_BINDING PRIMARY KEY (binding_id),
    CONSTRAINT uk_cpf_gwy_binding_key UNIQUE (environment_code, host_pattern, path_pattern, http_method, api_version, route_version),
    CONSTRAINT ck_cpf_gwy_binding_gateway CHECK (gateway_allowed_yn IN ('Y','N')),
    CONSTRAINT ck_cpf_gwy_binding_direct CHECK (direct_allowed_yn IN ('Y','N')),
    CONSTRAINT ck_cpf_gwy_binding_idempotent CHECK (idempotent_yn IN ('Y','N')),
    CONSTRAINT fk_cpf_gwy_binding_group FOREIGN KEY (server_group_id) REFERENCES GW_SERVER_GROUP (server_group_id)
) ENGINE=InnoDB;
ALTER TABLE GW_BINDING COMMENT = 'Gateway Versioned Binding';
CREATE INDEX ix_cpf_gwy_binding_route ON GW_BINDING (environment_code, route_id, binding_status);

CREATE TABLE GW_HEALTH_HISTORY (
