    network_status VARCHAR(30) NOT NULL,
    tcp_status VARCHAR(30) NOT NULL,
    tls_status VARCHAR(30) NOT NULL,
    application_status VARCHAR(30) NOT NULL,
    overall_status VARCHAR(30) NOT NULL,
    result_code VARCHAR(100) NULL,
    duration_ms BIGINT DEFAULT 0 NOT NULL,
    observed_at DATETIME NOT NULL,
    recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_GW_HEALTH_HISTORY PRIMARY KEY (health_history_id),
    CONSTRAINT fk_cpf_gwy_health_group FOREIGN KEY (server_group_id) REFERENCES GW_SERVER_GROUP (server_group_id)
) ENGINE=InnoDB;
ALTER TABLE GW_HEALTH_HISTORY COMMENT = 'Gateway Protocol 단계별 Health 불변 이력';
CREATE INDEX ix_cpf_gwy_health_member ON GW_HEALTH_HISTORY (server_group_id, instance_id, observed_at);
CREATE INDEX ix_cpf_gwy_health_status ON GW_HEALTH_HISTORY (overall_status, observed_at);

CREATE TABLE GW_SERVER_GROUP_MEMBER (
    server_group_id VARCHAR(100) NOT NULL,
    instance_id VARCHAR(100) NOT NULL,
    weight INT DEFAULT 1 NOT NULL,
    priority_no INT DEFAULT 0 NOT NULL,
    enabled_yn CHAR(1) DEFAULT 'Y' NOT NULL,
    effective_status VARCHAR(30) DEFAULT 'UNKNOWN' NOT NULL,
    fencing_token BIGINT DEFAULT 0 NOT NULL,
    created_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR(100) DEFAULT 'CPF' NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL ON UPDATE CURRENT_TIMESTAMP,
